"""Harness for SkyyShards 0.3.2 (CLEAN CLIENT LOG: totem item textures under Items/; build_skyyshards_0.3.2.py, generated by
tools/shards_0_3_2_patch.py from 0.3.1).

    python SkyyShards/test_skyyshards_0.3.2.py [--dir <empty folder inside tools/dev/scratch/>] [--keep]

Phases (fresh child JVMs, tools/harness_kit.py):
  A    verify   every class loads + initialises with -Xverify:all
  C    compare  0.3.1 -> 0.3.2: only version texts in the classes; non-class entries: manifest.json, the 20 totem ITEM documents (only their
                "Texture" field) and the 20 new Items/SkyyShards/Totem_<Name>.png files (byte-identical to the blocks' textures)
  T    assets   every item document in the jar: an item "Texture" never points under Blocks/ (vanilla: 465 of 466 item textures sit under
                Items/ / Resources/ / NPC/; the client refuses ours there - "Cannot use ... as texture for item"); every texture / model /
                icon / CustomModelTexture path the jar names exists in the jar or in Assets.zip; blocks keep their Blocks/ textures; ids
                unchanged (same document set as 0.3.1)
  AA   engine-access audit
Exit code 1 on any failure.
"""
import os, sys, json, zipfile

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, "tools"))
import harness_kit as HK

VERSION = "0.3.2"
JAR = os.path.abspath(HK.arg("--jar", os.path.join(HERE, "SkyyShards-%s.jar" % VERSION)))
OLD_JAR = os.path.join(HERE, "SkyyShards-0.3.1.jar")
SCRATCH = os.path.abspath(HK.arg("--dir", os.path.join(ROOT, "tools", "dev", "scratch", "shards032", "harness")))
PKG = "com.skyy.shards."
# the version texts only
EXPECT = {
    "SkyyShardsPlugin": ["~m setup"],
    "ShStore": ["~m save"],
    "CfgRows": ["~m header"],
    "CfgFn": ["~m opExport"],
}
ADDED = []
CMD = ("Server/Item/Items/SkyyShards/Totems/",)


def _items(z):
    out = {}
    for n in z.namelist():
        if n.startswith("Server/Item/Items/") and n.endswith(".json"):
            out[n] = json.loads(z.read(n).decode("utf-8-sig"))
    return out


_orig_compare = HK.run_compare


def run_compare(out, jar, old_jar, pkg, expect, added):
    """the kit's compare, then its non-class check replaced by the exact 0.3.2 expectation"""
    _orig_compare(out, jar, old_jar, pkg, expect, added)
    d = json.load(open(out))
    d["fails"] = [f for f in d["fails"] if not f.startswith("C: non-class entries changed")]
    za, zb = zipfile.ZipFile(old_jar), zipfile.ZipFile(jar)
    na, nb = set(za.namelist()), set(zb.namelist())
    fails = d["fails"]
    added_n = sorted(n for n in nb - na if not n.endswith(".class"))
    removed = sorted(n for n in na - nb if not n.endswith(".class"))
    if removed:
        fails.append("C: non-class entries removed: %s" % removed[:5])
    ia, ib = _items(za), _items(zb)
    tot = sorted(n for n, j in ib.items() if n.startswith(CMD[0]) and "Model" in j and "Texture" in j)
    want_new = sorted("Common/" + ib[n]["Texture"] for n in tot)
    if added_n != want_new or len(tot) != 20:
        fails.append("C: new non-class entries %s, want the %d totem item textures %s" % (added_n[:4], len(tot), want_new[:4]))
    changed = sorted(n for n in na & nb if not n.endswith(".class") and za.read(n) != zb.read(n))
    if changed != sorted(["manifest.json"] + tot):
        fails.append("C: changed non-class entries %s" % [c for c in changed if c not in tot][:6])
    for n in tot:
        a, b = dict(ia[n]), dict(ib[n])
        ta, tb = a.pop("Texture"), b.pop("Texture")
        if a != b or not ta.startswith("Blocks/SkyyShards/Totem_") or tb != "Items/" + ta[len("Blocks/"):]:
            fails.append("C: %s changed beyond its Texture (%s -> %s)" % (n, ta, tb))
        elif zb.read("Common/" + tb) != za.read("Common/" + ta) or zb.read("Common/" + ta) != za.read("Common/" + ta):
            fails.append("C: %s: the item texture is not byte-identical to the 0.3.1 one" % n)
    ma, mb = json.loads(za.read("manifest.json")), json.loads(zb.read("manifest.json"))
    for _m, _v in ((ma, "0.3.1"), (mb, VERSION)):
        if _m.pop("Version", None) != _v or _m.get("Name") != _v + " SkyyShards":
            fails.append("C: manifest Version / Name are not %s" % _v)
        _m.pop("Name", None)
    if ma != mb:
        fails.append("C: manifest changed beyond Version / Name")
    d["ok"] += 1
    d["notes"] = d.get("notes", []) + ["C: non-class: manifest + %d totem item documents (Texture only) + %d new Items/ textures" % (len(tot), len(added_n))]
    json.dump(d, open(out, "w"), indent=1)


HK.run_compare = run_compare      # the kit's builtin "compare" looks the name up at call time


def run_assets(out, jar, scratch, home):
    import serverjar
    K = HK.Child(out)
    z = zipfile.ZipFile(jar)
    zn = set(z.namelist())
    az = zipfile.ZipFile(serverjar.assets_zip())
    azn = set(az.namelist())
    its = _items(z)
    old = _items(zipfile.ZipFile(OLD_JAR))
    K.eq(sorted(its), sorted(old), "T the item documents (ids) are the 0.3.1 set")

    def exists(p):
        return ("Common/" + p) in zn or ("Common/" + p) in azn
    n_tex = 0
    for n, j in sorted(its.items()):
        t = j.get("Texture")
        if isinstance(t, str):
            n_tex += 1
            K.check(not t.startswith("Blocks/"), "T %s: item Texture %s is not under Blocks/" % (os.path.basename(n), t))
            K.check(exists(t), "T %s: item Texture %s exists" % (os.path.basename(n), t))
        for key in ("Model", "Icon"):
            if isinstance(j.get(key), str):
                K.check(exists(j[key]), "T %s: %s %s exists" % (os.path.basename(n), key, j[key]))
        bt = j.get("BlockType") or {}
        if bt.get("CustomModel"):
            K.check(exists(bt["CustomModel"]), "T %s: CustomModel exists" % os.path.basename(n))
        for cm in bt.get("CustomModelTexture", []):
            K.check(exists(cm["Texture"]) and cm["Texture"].startswith("Blocks/"), "T %s: block texture %s exists under Blocks/" % (os.path.basename(n), cm["Texture"]))
    K.eq(n_tex, 20, "T item documents with a Texture (the 20 totems)")
    # the in-hand item and its placed block look the same: same bytes behind both paths
    for n, j in its.items():
        if n.endswith("_Block.json"):
            continue
        b = its.get(n[:-5] + "_Block.json")
        if b and "Texture" in j:
            bt = b["BlockType"]["CustomModelTexture"][0]["Texture"]
            K.check(z.read("Common/" + j["Texture"]) == z.read("Common/" + bt), "T %s: item and block texture bytes are identical" % os.path.basename(n))
    # vanilla's own pattern (the evidence for the rule): item textures under Blocks/ are the rare exception
    vb = vt = 0
    for n in azn:
        if n.startswith("Server/Item/Items/") and n.endswith(".json"):
            try:
                t = json.loads(az.read(n).decode("utf-8-sig")).get("Texture")
            except ValueError:
                continue
            if isinstance(t, str):
                vt += 1
                vb += t.startswith("Blocks/")
    K.check(vt > 400 and vb <= 2, "T vanilla: %d of %d item textures under Blocks/" % (vb, vt))
    K.notes.append("T vanilla item textures under Blocks/: %d of %d" % (vb, vt))
    K.save()


if __name__ == "__main__":
    HK.run(name="SkyyShards", version=VERSION, jar=JAR, old_jar=OLD_JAR, pkg=PKG, scratch=SCRATCH, expect=EXPECT, added=ADDED,
           phases=[("assets", run_assets)], script=__file__)
